    logic [31:0]          max_comp_q [NumGroups];
    logic [31:0]          min_dur_q  [NumGroups];
    logic [31:0]          max_dur_q  [NumGroups];
    logic [NumGroups-1:0] seen_q;
    logic [StatWidth-1:0] total_q;
    logic [15:0]          err_q;

